using System.Globalization;
using System.Text.Json;
using Microsoft.Diagnostics.Tracing.Etlx;
using Microsoft.Diagnostics.Tracing.EventPipe;

if (args.Length != 1)
{
    throw new ArgumentException("Pass one EventPipe .nettrace file.");
}

var tracePath = Path.GetFullPath(args[0]);
var etlxPath = Path.ChangeExtension(tracePath, ".alloc.etlx");
TraceLog.CreateFromEventPipeDataFile(tracePath, etlxPath, new TraceLogOptions());
using var trace = new TraceLog(etlxPath);
var eventCounts = new Dictionary<string, int>();
var markers = new List<object>();
var self = new Dictionary<string, int>();
var inclusive = new Dictionary<string, int>();
var gcSelf = new Dictionary<string, int>();
var gcInclusive = new Dictionary<string, int>();
var targetedSelf = new Dictionary<string, int>();
var targetedInclusive = new Dictionary<string, int>();
var unresolvedSelf = new Dictionary<string, int>();
var unresolvedInclusive = new Dictionary<string, int>();
var nativeOrUnclassifiedSelf = new Dictionary<string, int>();
var nativeOrUnclassifiedInclusive = new Dictionary<string, int>();
var allocationSamplesByType = new Dictionary<string, (int Samples, long SampledBytes)>();
var allocationSamplesByTypeAndStack = new Dictionary<string, (string Type, string Stack, int Samples, long SampledBytes)>();
var stackSamples = 0;
var missingStacks = 0;
var allocationTickSamples = 0;
var allocationTickMissingStacks = 0;
var allocationTickSampledBytes = 0L;
var jitEventsInActual = new List<object>();
double? lastBackgroundJitStopMs = null;
var windows = new List<(double Start, double Stop, int Thread, int Process)>();
(double Start, int Thread, int Process)? pendingWindow = null;

foreach (var traceEvent in trace.Events)
{
    var eventKey = traceEvent.ProviderName + "/" + traceEvent.EventName;
    eventCounts[eventKey] = eventCounts.GetValueOrDefault(eventKey) + 1;
    if (traceEvent.ProviderName.Contains("BenchmarkDotNet", StringComparison.Ordinal))
    {
        markers.Add(new
        {
            Event = eventKey,
            Id = (int)traceEvent.ID,
            TimeMs = traceEvent.TimeStampRelativeMSec,
            traceEvent.ProcessID,
            traceEvent.ThreadID,
            Payload = traceEvent.PayloadNames.ToDictionary(name => name, name => traceEvent.PayloadByName(name)?.ToString())
        });
        if ((int)traceEvent.ID == 15)
        {
            pendingWindow = (traceEvent.TimeStampRelativeMSec, traceEvent.ThreadID, traceEvent.ProcessID);
        }
        else if ((int)traceEvent.ID == 16 && pendingWindow is { } start)
        {
            if (start.Thread != traceEvent.ThreadID || start.Process != traceEvent.ProcessID)
            {
                throw new InvalidOperationException("Actual iteration process or thread changed.");
            }
            windows.Add((start.Start, traceEvent.TimeStampRelativeMSec, start.Thread, start.Process));
            pendingWindow = null;
        }
    }
}

if (windows.Count == 0 || pendingWindow is not null)
{
    Console.WriteLine(JsonSerializer.Serialize(new { EventCounts = eventCounts, Markers = markers }));
    throw new InvalidOperationException("No complete WorkloadActual windows found; do not interpret the trace as steady-state samples.");
}

foreach (var traceEvent in trace.Events)
{
    if (traceEvent.ProviderName == "Microsoft-Windows-DotNETRuntime")
    {
        if (traceEvent.EventName == "TieredCompilation/BackgroundJitStop"
            && windows.Any(window => traceEvent.ProcessID == window.Process))
        {
            lastBackgroundJitStopMs = traceEvent.TimeStampRelativeMSec;
        }
        if (windows.Any(window => traceEvent.ProcessID == window.Process && traceEvent.TimeStampRelativeMSec >= window.Start
            && traceEvent.TimeStampRelativeMSec <= window.Stop)
            && (traceEvent.EventName.Contains("Jit", StringComparison.OrdinalIgnoreCase)
                || traceEvent.EventName.Contains("TieredCompilation", StringComparison.Ordinal)))
        {
            jitEventsInActual.Add(new { traceEvent.EventName, TimeMs = traceEvent.TimeStampRelativeMSec });
        }
    }

    if (traceEvent.ProviderName == "Microsoft-Windows-DotNETRuntime"
        && traceEvent.EventName == "GC/AllocationTick"
        && windows.Any(window => traceEvent.ProcessID == window.Process
            && traceEvent.ThreadID == window.Thread
            && traceEvent.TimeStampRelativeMSec >= window.Start
            && traceEvent.TimeStampRelativeMSec <= window.Stop))
    {
        allocationTickSamples++;
        var typeName = traceEvent.PayloadByName("TypeName")?.ToString() ?? "[missing type]";
        var amountValue = traceEvent.PayloadByName("AllocationAmount64")
            ?? traceEvent.PayloadByName("AllocationAmount");
        var sampledBytes = 0L;
        if (amountValue is not null)
        {
            long.TryParse(Convert.ToString(amountValue, CultureInfo.InvariantCulture), NumberStyles.Integer, CultureInfo.InvariantCulture, out sampledBytes);
        }
        allocationTickSampledBytes += sampledBytes;
        var typeTotals = allocationSamplesByType.GetValueOrDefault(typeName);
        allocationSamplesByType[typeName] = (typeTotals.Samples + 1, typeTotals.SampledBytes + sampledBytes);

        var allocationFrame = trace.GetCallStackForEvent(traceEvent);
        if (allocationFrame is null)
        {
            allocationTickMissingStacks++;
            continue;
        }

        var stackFrames = new List<string>();
        while (allocationFrame is not null && stackFrames.Count < 8)
        {
            var methodName = allocationFrame.CodeAddress.FullMethodName;
            stackFrames.Add(string.IsNullOrEmpty(methodName) ? "[unresolved]" : methodName);
            allocationFrame = allocationFrame.Caller;
        }

        var stack = string.Join(" <- ", stackFrames);
        var key = typeName + "\n" + stack;
        var stackTotals = allocationSamplesByTypeAndStack.GetValueOrDefault(key);
        allocationSamplesByTypeAndStack[key] = (typeName, stack, stackTotals.Samples + 1, stackTotals.SampledBytes + sampledBytes);
    }

    if (traceEvent.ProviderName != SampleProfilerTraceEventParser.ProviderName)
    {
        continue;
    }

    if (!windows.Any(window => traceEvent.ProcessID == window.Process && traceEvent.ThreadID == window.Thread
        && traceEvent.TimeStampRelativeMSec >= window.Start
        && traceEvent.TimeStampRelativeMSec <= window.Stop))
    {
        continue;
    }

    var frame = trace.GetCallStackForEvent(traceEvent);
    if (frame is null)
    {
        missingStacks++;
        continue;
    }

    stackSamples++;
    var leaf = true;
    var seen = new HashSet<string>();
    while (frame is not null)
    {
        var methodName = frame.CodeAddress.FullMethodName;
        if (string.IsNullOrEmpty(methodName))
        {
            methodName = "[unresolved]";
        }

        if (leaf)
        {
            self[methodName] = self.GetValueOrDefault(methodName) + 1;
            if (IsGcRelated(methodName))
            {
                gcSelf[methodName] = gcSelf.GetValueOrDefault(methodName) + 1;
            }
            if (IsTargeted(methodName))
            {
                targetedSelf[methodName] = targetedSelf.GetValueOrDefault(methodName) + 1;
            }
            if (IsUnresolved(methodName))
            {
                unresolvedSelf[methodName] = unresolvedSelf.GetValueOrDefault(methodName) + 1;
            }
            else if (IsNativeOrUnclassified(methodName))
            {
                nativeOrUnclassifiedSelf[methodName] = nativeOrUnclassifiedSelf.GetValueOrDefault(methodName) + 1;
            }
            leaf = false;
        }

        if (seen.Add(methodName))
        {
            inclusive[methodName] = inclusive.GetValueOrDefault(methodName) + 1;
            if (IsGcRelated(methodName))
            {
                gcInclusive[methodName] = gcInclusive.GetValueOrDefault(methodName) + 1;
            }
            if (IsTargeted(methodName))
            {
                targetedInclusive[methodName] = targetedInclusive.GetValueOrDefault(methodName) + 1;
            }
            if (IsUnresolved(methodName))
            {
                unresolvedInclusive[methodName] = unresolvedInclusive.GetValueOrDefault(methodName) + 1;
            }
            else if (IsNativeOrUnclassified(methodName))
            {
                nativeOrUnclassifiedInclusive[methodName] = nativeOrUnclassifiedInclusive.GetValueOrDefault(methodName) + 1;
            }
        }

        frame = frame.Caller;
    }
}

static bool IsGcRelated(string methodName)
    => methodName.Contains("GC", StringComparison.OrdinalIgnoreCase)
        || methodName.Contains("GarbageCollect", StringComparison.OrdinalIgnoreCase)
        || methodName.Contains("gc_heap", StringComparison.OrdinalIgnoreCase);

static bool IsTargeted(string methodName)
    => methodName.Contains("ConditionalWeakTable", StringComparison.Ordinal)
        || methodName.Contains("TryGetValueWorker", StringComparison.Ordinal)
        || methodName.Contains("GetValue(", StringComparison.Ordinal)
        || methodName.Contains("RuntimeHelpers.GetHashCode", StringComparison.Ordinal)
        || methodName.Contains("ParserConverter", StringComparison.Ordinal)
        || methodName.Contains("ParseDynamicCore", StringComparison.Ordinal)
        || methodName.Contains("ZeroOrMoreParser", StringComparison.Ordinal)
        || methodName.Contains("OrParser", StringComparison.Ordinal)
        || methodName.Contains("Cursol", StringComparison.Ordinal)
        || methodName.Contains("ExpectCharParser", StringComparison.Ordinal)
        || methodName.Contains("GVM", StringComparison.OrdinalIgnoreCase)
        || methodName.Contains("GenericVirtual", StringComparison.OrdinalIgnoreCase)
        || methodName.Contains("VirtualStub", StringComparison.OrdinalIgnoreCase);

static bool IsUnresolved(string methodName)
    => methodName is "[unresolved]" or "???" or "<unknown>"
        || methodName.Contains("[unknown]", StringComparison.OrdinalIgnoreCase);

static bool IsNativeOrUnclassified(string methodName)
    => !methodName.StartsWith("Marimo.", StringComparison.Ordinal)
        && !methodName.StartsWith("System.", StringComparison.Ordinal)
        && !methodName.StartsWith("Microsoft.", StringComparison.Ordinal)
        && !methodName.StartsWith("BenchmarkDotNet.", StringComparison.Ordinal)
        && !methodName.StartsWith("[", StringComparison.Ordinal)
        && !methodName.StartsWith("<unknown>", StringComparison.Ordinal);

var actualDurationMs = windows.Sum(window => window.Stop - window.Start);

Console.WriteLine(JsonSerializer.Serialize(new
{
    trace.EventCount,
    trace.EventsLost,
    StackSamples = stackSamples,
    MissingStacks = missingStacks,
    ActualExecutionThreadCpuSamplesPerSecond = actualDurationMs > 0 ? stackSamples / (actualDurationMs / 1000) : 0,
    ActualWindowCount = windows.Count,
    TotalActualWindowDurationMs = actualDurationMs,
    JitEventsInActual = jitEventsInActual,
    LastBackgroundJitStopMs = lastBackgroundJitStopMs,
    ActualWindows = windows.Select(window => new { window.Start, window.Stop, window.Thread, ProcessID = window.Process }),
    EventCounts = eventCounts.OrderByDescending(pair => pair.Value),
    Markers = markers,
    TopSelf = self.OrderByDescending(pair => pair.Value).Take(20).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    TopInclusive = inclusive.OrderByDescending(pair => pair.Value).Take(20).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    AllocationTickSamples = allocationTickSamples,
    AllocationTickMissingStacks = allocationTickMissingStacks,
    AllocationTickSampledBytes = allocationTickSampledBytes,
    AllocationSamplesByType = allocationSamplesByType.OrderByDescending(pair => pair.Value.Samples).Take(30).Select(pair => new { Type = pair.Key, pair.Value.Samples, pair.Value.SampledBytes }),
    TopAllocationSamplesByTypeAndStack = allocationSamplesByTypeAndStack.Values.OrderByDescending(value => value.Samples).Take(30).Select(value => new { value.Type, value.Stack, value.Samples, value.SampledBytes }),
    TargetedSelf = targetedSelf.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    TargetedInclusive = targetedInclusive.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    GcRelatedSelf = gcSelf.OrderByDescending(pair => pair.Value).Take(20).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    GcRelatedInclusive = gcInclusive.OrderByDescending(pair => pair.Value).Take(20).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    UnresolvedSelf = unresolvedSelf.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    UnresolvedInclusive = unresolvedInclusive.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    NativeOrUnclassifiedSelf = nativeOrUnclassifiedSelf.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples }),
    NativeOrUnclassifiedInclusive = nativeOrUnclassifiedInclusive.OrderByDescending(pair => pair.Value).Select(pair => new { Method = pair.Key, Samples = pair.Value, PercentOfSamples = 100.0 * pair.Value / stackSamples })
}, new JsonSerializerOptions { WriteIndented = true }));

